import pandas as pd

invoices = pd.read_csv('/app/dataset/invoices.csv')

def get_ld(val):
    s = str(abs(val)).replace('.', '').lstrip('0')
    return int(s[0]) if s else None

invoices['ld_net'] = invoices['net_amount'].apply(get_ld)

for sid, grp in invoices.groupby('seller_id'):
    vc = grp['ld_net'].value_counts()
    for d, count in vc.items():
        if len(grp) >= 5 and count / len(grp) >= 0.70:
            print(f'Seller {sid}: digit {d} appeared {count}/{len(grp)} ({count/len(grp):.2%})')
"

python3 -c "
import pandas as pd
invoices = pd.read_csv('/app/dataset/invoices.csv')

curr_bid = None
streak = 0
streaks = []
for idx, bid in enumerate(invoices['buyer_id']):
    if bid == curr_bid:
        streak += 1
    else:
        if streak >= 3:
            streaks.append((curr_bid, idx - streak, idx - 1, streak))
        curr_bid = bid
        streak = 1
if streak >= 3:
    streaks.append((curr_bid, len(invoices) - streak, len(invoices) - 1, streak))

print('All consecutive buyer streaks >= 3:')
for s in streaks:
    print(s)
"

