import os, time

target_time = os.path.getmtime('/app/dataset/invoices.csv')
print('Invoices mtime:', target_time, time.ctime(target_time))

matches = []
for root, dirs, files in os.walk('/'):
    if any(p in root for p in ['/proc', '/sys', '/dev']):
        continue
    for f in files:
        p = os.path.join(root, f)
        try:
            mt = os.path.getmtime(p)
            if abs(mt - target_time) < 3600 * 24: # within 24 hours
                matches.append((p, mt))
        except:
            pass

for p, mt in sorted(matches, key=lambda x: x[1]):
    print(p, time.ctime(mt))
"

